// Run once for all items, before batching, so identifiers never reset per batch.
return $input.all().map((item, index) => {
  const message = item.json['Email Text'];
  if (typeof message !== 'string') throw new Error('CSV requires an Email Text column.');
  if (message.length > 10000) throw new Error('A message exceeds the 10,000-character input limit.');
  return { json: { id: index + 1, mensagem: message, label_real: String(item.json['Email Type'] || '') }, pairedItem: { item: index } };
});

// Lexical signals only: never fetch, resolve or open an address from a message.
const incoming = $input.all();
const lote = incoming.map(({ json: source }) => {
  const urls = source.mensagem.match(/https?:\/\/[^\s<>"']+/gi) || [];
  const reasons = new Set();
  for (const url of urls) {
    const authority = url.match(/^https?:\/\/([^/?#]+)/i)?.[1] || '';
    const hostPort = authority.split('@').pop().toLowerCase();
    const host = hostPort.startsWith('[') ? hostPort.split(']')[0] + ']' : hostPort.replace(/:\d+$/, '');
    if (authority.includes('@')) reasons.add('User information in URL authority');
    const ipv4 = host.split('.');
    if ((ipv4.length === 4 && ipv4.every(part => /^\d{1,3}$/.test(part) && Number(part) <= 255)) || /^\[[0-9a-f:]+\]$/i.test(host)) reasons.add('IP-address URL');
    if (url.length > 100) reasons.add('URL longer than 100 characters');
    if (['bit.ly', 'tinyurl.com', 't.co', 'goo.gl', 'is.gd'].some(domain => host === domain || host.endsWith('.' + domain))) reasons.add('URL shortener');
    if (/\.(xyz|top|tk|ml|ga|cf)$/.test(host)) reasons.add('Uncommon top-level domain');
  }
  return { ...source, urls, url_suspeita: reasons.size > 0, motivos_url: [...reasons] };
});
// Ground-truth labels are deliberately excluded from the model input.
const prompt_lote = lote.map(({ id, mensagem, urls, url_suspeita, motivos_url }) => ({ id, mensagem, urls, url_suspeita, motivos_url }));
return [{ json: { lote, prompt_lote }, pairedItem: incoming.map((_, item) => ({ item })) }];

return $input.all().map((item, index) => {
  const result = item.json;
  const valid = result.analysis_status === 'ok' && Number.isInteger(result.score) && result.score >= 0 && result.score <= 100 && Number.isInteger(result.confianca_ia) && result.confianca_ia >= 0 && result.confianca_ia <= 100;
  return { json: { source_id: result.id, mensagem: result.mensagem,
    analysis_status: valid ? 'ok' : 'analysis_error', error_reason: valid ? null : (result.error_reason || 'invalid_schema'),
    score: valid ? result.score : null, confianca_ia: valid ? result.confianca_ia : null,
    suspeito: valid ? result.score >= 40 : null,
    classificacao: !valid ? 'ERRO DE ANALISE' : result.score >= 71 ? 'ALTO RISCO' : result.score >= 40 ? 'MEDIO RISCO' : 'BAIXO RISCO',
    motivos: Array.isArray(result.motivos) ? result.motivos.join('; ') : 'Analysis unavailable. Human review required.',
    timestamp: new Date().toISOString(), model: 'llama-3.3-70b-versatile', prompt_version: 'portfolio-v1' }, pairedItem: { item: index } };
});

// Resolve the current linked batch, not the first execution of a looping node.
const batch = $('Analyze URLs').item.json.lote;
if (!Array.isArray(batch) || !batch.length) throw new Error('The linked input batch is missing.');
const response = $input.first().json;
function errorRow(source, code) {
  return { json: { id: source.id, mensagem: source.mensagem, label_real: source.label_real,
    analysis_status: 'analysis_error', error_reason: code, score: null, confianca_ia: null,
    suspeito: null, motivos: ['Analysis unavailable. Human review required.'] }, pairedItem: { item: 0 } };
}
function failBatch(code) { return batch.map(source => errorRow(source, code)); }
if (response.error) return failBatch('provider_error');
let raw = response.text ?? response.output ?? response.response;
if (typeof raw !== 'string' || !raw.trim()) return failBatch('missing_response');
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let results;
try { results = JSON.parse(raw); } catch { return failBatch('invalid_json'); }
if (!Array.isArray(results) || results.length !== batch.length) return failBatch('result_count_mismatch');
const expected = new Set(batch.map(source => source.id));
const seen = new Set();
for (const result of results) {
  if (!result || typeof result !== 'object' || Array.isArray(result) || !Number.isInteger(result.id) || !expected.has(result.id) || seen.has(result.id)) return failBatch('id_mismatch');
  seen.add(result.id);
}
const byId = new Map(results.map(result => [result.id, result]));
return batch.map(source => {
  const result = byId.get(source.id);
  const bounded = value => Number.isInteger(value) && value >= 0 && value <= 100;
  if (!source.mensagem.trim()) return errorRow(source, 'empty_message');
  if (result.analysis_status === 'analysis_error') return errorRow(source, 'model_abstained');
  if (result.analysis_status !== 'ok' || !bounded(result.score) || !bounded(result.confianca_ia) || typeof result.suspeito !== 'boolean' || result.suspeito !== (result.score >= 40) || !Array.isArray(result.motivos) || !result.motivos.length || result.motivos.length > 8 || !result.motivos.every(reason => typeof reason === 'string' && reason.trim() && reason.length <= 300)) return errorRow(source, 'invalid_schema');
  return { json: { id: source.id, mensagem: source.mensagem, label_real: source.label_real,
    analysis_status: 'ok', error_reason: null, score: result.score, confianca_ia: result.confianca_ia,
    suspeito: result.score >= 40, motivos: result.motivos }, pairedItem: { item: 0 } };
});
